  /* ==========================================================================
     19. 记住当前第几屏：退出应用回到首页时，停在你刚才那一屏
     ========================================================================== */
  /* ------------------------------------------------------------------------
     翻页胶囊（手机端）—— 2026-10-31 修
     实测：手机上点圆点、调 __m2GoScreen(1)/(2)，track.scrollLeft 一直是 0
     （track 能滚、scroll-snap 也在，就是没人真去滚它 —— 原版给圆点绑的 click
      在手机版里没生效）。后果有两个：
        ① 点圆点翻不动页；
        ② trackScreen 存下来的 te2_scr 永远是 0，于是"点应用再返回"总落到第 1 屏。
     这里不再依赖圆点自己的 click，直接滚 track，并把位置写回 te2_scr。
     用事件委托（capture）绑在 document 上，页面重建后依然有效。
     ------------------------------------------------------------------------ */
  function pagerEls() {
    var track = $('#pg-home > .track') || $('.track');
    var dots = $$('#sdots .dot');
    if (!track || !dots.length) return null;
    return { track: track, dots: dots };
  }
  function pagerIndex(e) {
    var w = e.track.clientWidth || 1;
    return Math.max(0, Math.min(e.dots.length - 1, Math.round(e.track.scrollLeft / w)));
  }
  function pagerPaint(e, i, save) {
    e.dots.forEach(function (dt, k) {
      dt.classList.toggle('on', k === i);
      dt.setAttribute('aria-current', k === i ? 'true' : 'false');
    });
    /* save===false 时只画圆点、不写存档：
       页面刚起来时 track 还在第 1 屏，这时写会把上次记住的页码冲成 0，
       "点应用再返回"就永远回不到原来那屏。 */
    if (save !== false) {
      try { if (localStorage.getItem('te2_scr') !== String(i)) localStorage.setItem('te2_scr', String(i)); } catch (x) {}
    }
  }
  function pagerGo(n, smooth) {
    var e = pagerEls();
    if (!e) return;
    var k = Math.max(0, Math.min(e.dots.length - 1, n | 0));
    var left = k * e.track.clientWidth;
    /* 直接定位，不用 smooth：手机版里 smooth 滚动会被后面每 900ms 的守护重排打断，
       表现就是"点第 2 屏、停在第 1 屏"。定位完再补一次，防 snap 抢回去。 */
    try { e.track.scrollTo({ left: left, behavior: 'auto' }); }
    catch (x) { e.track.scrollLeft = left; }
    pagerPaint(e, k);
    setTimeout(function () {
      var cur = pagerEls();
      if (cur && Math.abs(cur.track.scrollLeft - k * cur.track.clientWidth) > 8) {
        try { cur.track.scrollTo({ left: k * cur.track.clientWidth, behavior: 'auto' }); }
        catch (x) { cur.track.scrollLeft = k * cur.track.clientWidth; }
      }
    }, 320);
  }
  function pager() {
    if (root.getAttribute('data-mh') !== 'phone') return;
    var e = pagerEls();
    if (!e) return;
    try { pagerPaint(e, pagerIndex(e), false); } catch (x) {}
    if (window.__m2PagerWired) return;
    window.__m2PagerWired = 1;
    d.addEventListener('click', function (ev) {
      var dot = ev.target && ev.target.closest ? ev.target.closest('#sdots .dot') : null;
      if (!dot) return;
      var cur = pagerEls();
      if (!cur) return;
      var k = cur.dots.indexOf(dot);
      if (k < 0) return;
      ev.preventDefault(); ev.stopPropagation();
      if (ev.stopImmediatePropagation) ev.stopImmediatePropagation();
      pagerGo(k);
    }, true);
    d.addEventListener('scroll', function (ev) {
      var t = ev.target;
      if (!t || t.nodeType !== 1) return;
      if (t.id === 'track' || (t.className && t.className.toString().indexOf('track') >= 0)) {
        var cur = pagerEls();
        if (cur) { try { pagerPaint(cur, pagerIndex(cur)); } catch (x) {} }
      }
    }, true);
  }

  function trackScreen() {
    if (root.getAttribute('data-mh') !== 'phone') return;
    var dots = $$('#sdots .dot');
    if (!dots.length) return;
    window.__m2GoScreen = function (n) { pagerGo(n); };
    /* ★ 2026-10-31：这里原来在启动时 save() 一次、还挂了圆点 class 的 MutationObserver，
       于是页面一加载就把 te2_scr 写成 0（当前 track 还在第 1 屏），
       "点应用再返回"永远回到第 1 屏。存档现在只由 pager() 在真的翻页/滚动时写。 */
  }

  /* ==========================================================================
     20. 群聊 / 心情 / 待办：外壳没有这三个"页"，点了要回首页滚到对应卡片
     ========================================================================== */
  function scrollApps() {
    if (root.getAttribute('data-mh') !== 'phone') return;
    if (window.__m2ScrollWired) return;
    window.__m2ScrollWired = 1;
    var map = { group: '.sb-chat', mood: '.sb-mood', todo: '.sb-todo' };
    document.addEventListener('click', function (e) {
      var hit = e.target && e.target.closest ? e.target.closest('[data-m2scroll]') : null;
      if (!hit) return;
      var key = hit.getAttribute('data-m2scroll');
      var sel = map[key];
      if (!sel) return;
      e.preventDefault(); e.stopPropagation();
      if (e.stopImmediatePropagation) e.stopImmediatePropagation();
      try {
        document.querySelectorAll('.page').forEach(function (p) { p.classList.toggle('on', p.id === 'pg-home'); });
        var target = document.querySelector(sel);
        if (target) target.scrollIntoView({ block: 'center' });
      } catch (x) {}
    }, true);
  }

  /* 星海吊牌后面那句" · 还没搬"去掉 */
  function treeClean() {
    if (root.getAttribute('data-mh') !== 'phone') return;
    $$('.sb-rooms .cell2 .cn, .sb-rooms .cell2 .en').forEach(function (e) {
      var t = (e.textContent || '').replace(/\s*[·•]?\s*还没搬\s*/g, '').trim();
      if (t && t !== e.textContent) e.textContent = t;
    });
  }

  /* ==========================================================================
     21. 树上那 7 个吊牌：原来写的是裸 key（star/home/map…），
         外壳只认 app:xxx，所以点了没反应。这里补齐前缀。
     ========================================================================== */
  var TREE_OPEN = {
    star: 'app:star', home: 'app:home', map: 'app:map', diary: 'app:diary',
    /* ★ 7.96：这里原来写的是 app:chat —— 树上那枚「群聊」吊牌因此打开的是**单聊页**。
       群聊的入口是外壳的 gcOpen()，对应的 key 就是 group。 */
    roster: 'app:roster', group: 'app:group', stk: 'app:stk', stickers: 'app:stk',
    letters: 'app:letters', memory: 'app:memory', worldbook: 'app:worldbook'
  };
  function treeLinks() {
    if (root.getAttribute('data-mh') !== 'phone') return;
    $$('.sb-rooms .cell2').forEach(function (c) {
      var k = (c.getAttribute('data-open') || '').trim();
      if (!k) {
        var en = (c.querySelector('.en') || {}).textContent || '';
        if (/Stickers|表情包/i.test(en + (c.textContent || ''))) k = 'stk';
      }
      var to = TREE_OPEN[k];
      if (to && k !== to) c.setAttribute('data-open', to);
      /* 再加一道"直连"兜底：直接叫父窗口切页，不依赖文档那层 data-open 拦截 */
      if (!c.getAttribute('data-m2direct')) {
        c.setAttribute('data-m2direct', '1');
        c.addEventListener('click', function (e) {
          var key = String(c.getAttribute('data-open') || '');
          var page = key.replace(/^app:/, '');
          if (!page) return;
          var par = null; try { par = window.parent; } catch (x) {}
          if (!par) return;
          /* ★ 7.96：先问外壳「这个 key 该开哪儿」——外壳用同一张 MAP：
             group→gcOpen()、roster→aiInfoOpen()、stickers→stkOpen()、home→家园…
             以前这里硬编码 parent.nav(page)：nav 只认页面 id，
             group / roster / stickers 这些没有页面的 key 会掉回首页或者干脆开错页。 */
          var ok = null;
          try { ok = par.jhOpenKey; } catch (x) {}
          var fn = null;
          try { fn = par.nav; } catch (x) {}
          if (typeof ok === 'function') {
            e.preventDefault(); e.stopPropagation();
            if (e.stopImmediatePropagation) e.stopImmediatePropagation();
            try { ok.call(par, key); } catch (x) {}
            return;
          }
          if (typeof fn === 'function') {
            e.preventDefault(); e.stopPropagation();
            if (e.stopImmediatePropagation) e.stopImmediatePropagation();
            try { fn.call(par, page); } catch (x) {}
          }
        }, true);
      }
    });
  }

